5	
6	export type Item = {
7	  type: string;
8	  material?: string;
9	  enchantment?: number;
10	  cursed?: boolean;
11	};
12	
13	const PROCESSING_FEE = 5;
14	
15	const BASE_PREMIUM_BY_ITEM_TYPE: Record<string, number> = {
16	  sword: 100,
17	  amulet: 60,
18	  staff: 80,
19	  potion: 40,
20	  rune: 25,
21	  moonstone: 25,
22	};
23	
24	const CURSED_SURCHARGE_RATE = 0.5;
25	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
26	const HIGH_ENCHANTMENT_THRESHOLD = 5;
27	
28	const basePremiumOf = (item: Item): number =>
29	  BASE_PREMIUM_BY_ITEM_TYPE[item.type];
30	
31	const surchargeRateOf = (item: Item): number =>
32	  (item.cursed ? CURSED_SURCHARGE_RATE : 0) +
33	  ((item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD
34	    ? HIGH_ENCHANTMENT_SURCHARGE_RATE
35	    : 0);
36	
37	const surchargeOf = (item: Item): number =>
38	  basePremiumOf(item) * surchargeRateOf(item);
39	
40	const sumBasePremiums = (items: Item[]): number =>
41	  items.reduce((sum, item) => sum + basePremiumOf(item), 0);
42	
43	const sumItemSurcharges = (items: Item[]): number =>
44	  items.reduce((sum, item) => sum + surchargeOf(item), 0);
45	
46	// Policy-level modifiers are whole percentages of the policy base premium.
47	// Applying them as `amount * percent / 100` keeps the arithmetic exact:
48	// `100 * 110 / 100` is 110, whereas `100 * 1.1` is 110.00000000000001.
49	const applyPercentage = (amount: number, percent: number): number =>
50	  (amount * percent) / 100;
51	
52	const FIRST_INSURANCE_SURCHARGE_PERCENTAGE = 10;
53	const LOYALTY_DISCOUNT_PERCENTAGE = 20;
54	const LOYALTY_YEARS_THRESHOLD = 2;
55	
56	const loyaltyDiscountPercentageOf = (customer: Customer): number =>
57	  customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD
58	    ? LOYALTY_DISCOUNT_PERCENTAGE
59	    : 0;
60	
61	const FOLLOW_UP_DISCOUNT_PERCENTAGE = 15;
62	const FOLLOW_UP_CONTRACTS_THRESHOLD = 1;
63	
64	const followUpDiscountPercentageOf = (customer: Customer): number =>
65	  customer.previousContracts >= FOLLOW_UP_CONTRACTS_THRESHOLD
66	    ? FOLLOW_UP_DISCOUNT_PERCENTAGE
67	    : 0;
68	
69	const policyPercentageDeltaOf = (customer: Customer): number =>
70	  FIRST_INSURANCE_SURCHARGE_PERCENTAGE -
71	  loyaltyDiscountPercentageOf(customer) -
72	  followUpDiscountPercentageOf(customer);
73	
74	const BLOCK_SIZE = 3;
75	const BLOCK_BASE_PREMIUM = 60;
76	
77	const isComponentBlock = (sameTypeGroup: Item[]): boolean =>
78	  sameTypeGroup.length === BLOCK_SIZE;
79	
80	const groupByType = (items: Item[]): Item[][] => {
81	  const groups = new Map<string, Item[]>();
82	  for (const item of items) {
83	    const group = groups.get(item.type) ?? [];
84	    group.push(item);
85	    groups.set(item.type, group);
86	  }
87	  return [...groups.values()];
88	};
89	
90	const basePremiumOfGroup = (sameTypeGroup: Item[]): number =>
91	  isComponentBlock(sameTypeGroup)
92	    ? BLOCK_BASE_PREMIUM
93	    : sumBasePremiums(sameTypeGroup);
94	
95	const policyBasePremiumOf = (items: Item[]): number =>
96	  groupByType(items).reduce((sum, group) => sum + basePremiumOfGroup(group), 0);
97	
98	export const quote = (customer: Customer, items: Item[]): number => {
99	  for (const item of items) {
100	    if (!(item.type in BASE_PREMIUM_BY_ITEM_TYPE)) {
101	      throw new Error(`Unknown item type: ${item.type}`);
102	    }
103	  }
104	
105	  const policyBasePremium = policyBasePremiumOf(items);
106	  const policyPercentageAdjustment = applyPercentage(
107	    policyBasePremium,
108	    policyPercentageDeltaOf(customer),
109	  );
110	
111	  return Math.ceil(
112	    policyBasePremium +
113	      sumItemSurcharges(items) +
114	      policyPercentageAdjustment +
115	      PROCESSING_FEE,
116	  );
117	};
118	
119	export const claim = (): number => {
120	  return undefined as unknown as number;
121	};
